<script setup>
import { computed, ref } from 'vue'
const hotspot=ref(35), mapping=ref('spread')
const loads=computed(()=>Array.from({length:24},(_,i)=>Math.min(100,18+(mapping.value==='clustered'&&[2,5,8,11,14,17].includes(i)?hotspot.value:Math.round(hotspot.value/3)))))
const worst=computed(()=>Math.max(...loads.value))
</script>
<template><section class="noc arch-overlay"><header><b>4×4 MESH TRAFFIC</b><span>hottest link {{worst}}%</span></header><svg viewBox="0 0 420 255"><g class="links"><line v-for="(load,i) in loads" :key="i" :x1="45+(i%3)*130" :y1="35+Math.floor(i/6)*64" :x2="i<12?115+(i%3)*130:45+(i%3)*130" :y2="i<12?35+Math.floor(i/3)*64:95+Math.floor((i-12)/3)*64" :style="{stroke:load>70?'#f16bb5':'#17d9ff',strokeWidth:3+load/20}"/><circle v-for="i in 16" :key="'n'+i" :cx="45+((i-1)%4)*100" :cy="35+Math.floor((i-1)/4)*64" r="16"/><text v-for="i in 16" :key="'t'+i" :x="45+((i-1)%4)*100" :y="39+Math.floor((i-1)/4)*64">{{i-1}}</text></g></svg><footer><button @click="mapping='spread'" :class="{on:mapping==='spread'}">Spread</button><button @click="mapping='clustered'" :class="{on:mapping==='clustered'}">Hotspot</button><label>hotspot <input v-model.number="hotspot" type="range" min="20" max="100"></label></footer></section></template>
<style scoped>.noc{right:0;bottom:0;width:600px;padding:16px;border-radius:20px;transform:scale(.65);transform-origin:bottom right}.noc header,.noc footer{display:flex;align-items:center;justify-content:space-between;color:#bed0df;font-size:12px}.noc header b{color:#17d9ff}.noc svg{width:100%;height:240px}.links line{opacity:.8;filter:drop-shadow(0 0 5px currentColor)}.links circle{fill:#07142d;stroke:#b9ff33;stroke-width:2}.links text{fill:white;text-anchor:middle;font-size:10px}.noc button{font-size:11px;padding:5px 9px}.noc button.on{background:#087d99;color:white}.noc label{display:flex;gap:7px;align-items:center}</style>
